-- GymLogger schema.
-- Conventions for every client (phone PWA, future watch app, Claude):
--  * ids are UUIDs generated by the client; writes are upserts (ON CONFLICT (id)).
--  * user_id defaults to auth.uid(); the service-role importer must set it explicitly.
--  * updated_at is maintained by a trigger (server clock) so clients can pull "changed since X".
--  * deleted_at is a soft delete so deletions can sync to other devices.
--  * RLS is enabled here with no policies (= deny all); policies come in the next migration.

create function public.set_updated_at() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------- exercises
create table public.exercises (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name           text not null,
  equipment      text check (equipment in ('barbell', 'dumbbell', 'cable', 'machine', 'bodyweight', 'other')),
  unilateral     boolean not null default false,
  dumbbell_pair  boolean not null default false,
  load_type      text not null default 'weighted' check (load_type in ('weighted', 'bodyweight', 'assisted')),
  rep_min        integer check (rep_min > 0),
  rep_max        integer check (rep_max > 0),
  increment_kg   numeric(5, 2) check (increment_kg > 0),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz,
  check (rep_min is null or rep_max is null or rep_min <= rep_max),
  unique (user_id, name)
);

-- ------------------------------------------------------------------ routines
create table public.routines (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name        text not null,
  position    integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz,
  unique (user_id, name)
);

create table public.routine_exercises (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null default auth.uid() references auth.users (id) on delete cascade,
  routine_id      uuid not null references public.routines (id) on delete cascade,
  exercise_id     uuid not null references public.exercises (id),
  position        integer not null,
  target_sets     integer not null default 3 check (target_sets > 0),
  superset_group  integer,
  priority        integer not null default 1 check (priority >= 1),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  deleted_at      timestamptz,
  unique (routine_id, exercise_id)
);
create index routine_exercises_routine_idx on public.routine_exercises (routine_id, position);

-- ------------------------------------------------------------------ sessions
create table public.sessions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  routine_id  uuid references public.routines (id),
  title       text not null,
  started_at  timestamptz not null,
  ended_at    timestamptz,
  notes       text,
  source      text not null default 'app' check (source in ('app', 'hevy_import')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  deleted_at  timestamptz,
  check (ended_at is null or ended_at >= started_at)
);
create index sessions_routine_idx on public.sessions (routine_id, started_at desc);
create index sessions_started_idx on public.sessions (user_id, started_at desc);

create table public.sets (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  session_id   uuid not null references public.sessions (id) on delete cascade,
  exercise_id  uuid not null references public.exercises (id),
  set_no       integer not null check (set_no > 0),
  side         text check (side in ('L', 'R')),
  weight_kg    numeric(6, 2) check (weight_kg >= 0),
  reps         integer check (reps >= 0),
  is_warmup    boolean not null default false,
  logged_at    timestamptz not null default now(),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
-- One row per (set number, side) of an exercise in a session. NULL side counts as one value.
create unique index sets_position_uq on public.sets (session_id, exercise_id, set_no, side) nulls not distinct
  where deleted_at is null;
create index sets_exercise_idx on public.sets (exercise_id, logged_at desc);

-- Free-text note about one exercise in one session (Hevy "exercise_notes"), e.g. "Back to 108".
create table public.session_exercise_notes (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  session_id   uuid not null references public.sessions (id) on delete cascade,
  exercise_id  uuid not null references public.exercises (id),
  note         text not null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create unique index session_exercise_notes_uq on public.session_exercise_notes (session_id, exercise_id)
  where deleted_at is null;

-- ------------------------------------------------------------------- plans
create table public.planned_sessions (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null default auth.uid() references auth.users (id) on delete cascade,
  routine_id          uuid not null references public.routines (id),
  created_by          text not null check (created_by in ('rules', 'claude')),
  status              text not null default 'pending' check (status in ('pending', 'used', 'superseded')),
  notes               text,
  used_by_session_id  uuid references public.sessions (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index planned_sessions_routine_idx on public.planned_sessions (routine_id, status, created_at desc);

create table public.planned_sets (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null default auth.uid() references auth.users (id) on delete cascade,
  planned_session_id  uuid not null references public.planned_sessions (id) on delete cascade,
  exercise_id         uuid not null references public.exercises (id),
  set_no              integer not null check (set_no > 0),
  target_weight_kg    numeric(6, 2) check (target_weight_kg >= 0),
  target_reps_min     integer check (target_reps_min >= 0),
  target_reps_max     integer check (target_reps_max >= 0),
  note                text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  check (target_reps_min is null or target_reps_max is null or target_reps_min <= target_reps_max),
  unique (planned_session_id, exercise_id, set_no)
);

-- ---------------------------------------------------- updated_at + RLS on all
do $$
declare t text;
begin
  foreach t in array array['exercises', 'routines', 'routine_exercises', 'sessions', 'sets',
                           'session_exercise_notes', 'planned_sessions', 'planned_sets']
  loop
    execute format('create trigger %I before update on public.%I
                    for each row execute function public.set_updated_at()', t || '_set_updated_at', t);
    execute format('alter table public.%I enable row level security', t);
  end loop;
end;
$$;

-- ------------------------------------------------------------------ comments
comment on table public.exercises is
  'Exercise catalog. One row per exercise with its progression settings (rep range, weight step).';
comment on column public.exercises.id is 'Client-generated UUID.';
comment on column public.exercises.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.exercises.name is 'Exercise name, unique per user (Hevy-style, e.g. "Bench Press (Dumbbell)").';
comment on column public.exercises.equipment is 'barbell | dumbbell | cable | machine | bodyweight | other.';
comment on column public.exercises.unilateral is
  'true = done one side at a time: each set is logged as two rows in sets (side L and side R). For progression a set''s result is the LOWER rep count of L and R.';
comment on column public.exercises.dumbbell_pair is
  'true = two dumbbells, one per hand: sets.weight_kg is the PAIR TOTAL (24 kg lateral raise = 2 x 12 kg). false for single-dumbbell or non-dumbbell exercises.';
comment on column public.exercises.load_type is
  'weighted = weight_kg is the load; bodyweight = reps only, weight_kg usually null; assisted = weight_kg is the ASSISTANCE, so progress means LOWER weight.';
comment on column public.exercises.rep_min is 'Bottom of the target rep range (double progression). Null = not set.';
comment on column public.exercises.rep_max is 'Top of the target rep range. Reaching it on all working sets triggers a weight increase. Null = not set.';
comment on column public.exercises.increment_kg is
  'Smallest weight step to move up (or down for assisted). Null = unknown: the plan then keeps the weight and says the increment is not set. Editable per exercise (different gyms have different steps).';
comment on column public.exercises.created_at is 'Row creation time (server clock).';
comment on column public.exercises.updated_at is 'Last change (server clock, set by trigger). Clients sync with updated_at > last_pull.';
comment on column public.exercises.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.routines is 'Workout templates, e.g. "Workout A". A session may belong to one routine.';
comment on column public.routines.id is 'Client-generated UUID.';
comment on column public.routines.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.routines.name is 'Routine name, unique per user.';
comment on column public.routines.position is 'Display order in the routine list (ascending).';
comment on column public.routines.created_at is 'Row creation time (server clock).';
comment on column public.routines.updated_at is 'Last change (server clock, set by trigger).';
comment on column public.routines.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.routine_exercises is 'Which exercises a routine contains, in order, with the target number of sets.';
comment on column public.routine_exercises.id is 'Client-generated UUID.';
comment on column public.routine_exercises.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.routine_exercises.routine_id is 'The routine this row belongs to.';
comment on column public.routine_exercises.exercise_id is 'The exercise performed.';
comment on column public.routine_exercises.position is 'Order of the exercise inside the routine (ascending).';
comment on column public.routine_exercises.target_sets is 'Number of working sets planned for this exercise.';
comment on column public.routine_exercises.superset_group is 'Exercises in the same routine sharing this number are alternated as a superset. Null = not in a superset.';
comment on column public.routine_exercises.priority is '1 = never skip; higher numbers are skipped first when short on time.';
comment on column public.routine_exercises.created_at is 'Row creation time (server clock).';
comment on column public.routine_exercises.updated_at is 'Last change (server clock, set by trigger).';
comment on column public.routine_exercises.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.sessions is 'One workout performed on one day. Its sets are in the sets table.';
comment on column public.sessions.id is 'Client-generated UUID (for Hevy imports: deterministic from title + start time).';
comment on column public.sessions.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.sessions.routine_id is 'Routine followed, or null for free-form/legacy sessions (they still count as per-exercise history).';
comment on column public.sessions.title is 'Name as typed or imported, e.g. "Workout B" or "Workout B Midtown".';
comment on column public.sessions.started_at is 'Start time (timestamptz; the Hevy export is Europe/Berlin local time).';
comment on column public.sessions.ended_at is 'End time. Null while the session is still in progress.';
comment on column public.sessions.notes is 'Free-text notes about the session.';
comment on column public.sessions.source is 'app = logged in the app; hevy_import = loaded from the Hevy CSV export.';
comment on column public.sessions.created_at is 'Row creation time (server clock).';
comment on column public.sessions.updated_at is 'Last change (server clock, set by trigger).';
comment on column public.sessions.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.sets is 'One performed set (one row per side for unilateral exercises). The core training log.';
comment on column public.sets.id is 'Client-generated UUID.';
comment on column public.sets.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.sets.session_id is 'Session this set belongs to.';
comment on column public.sets.exercise_id is 'Exercise performed.';
comment on column public.sets.set_no is 'Order of the set within this exercise in the session, starting at 1. Warm-ups included. For unilateral exercises L and R of the same set share the number.';
comment on column public.sets.side is 'null = both sides together; L or R = one side of a unilateral exercise.';
comment on column public.sets.weight_kg is
  'Load in kg. Dumbbell-pair exercises: PAIR TOTAL. Assisted exercises: the ASSISTANCE (lower = better). Null for pure bodyweight.';
comment on column public.sets.reps is 'Repetitions completed.';
comment on column public.sets.is_warmup is 'true = warm-up set, excluded from progression and from last_performance.';
comment on column public.sets.logged_at is 'When the set was logged (device clock).';
comment on column public.sets.created_at is 'Row creation time (server clock).';
comment on column public.sets.updated_at is 'Last change (server clock, set by trigger).';
comment on column public.sets.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.session_exercise_notes is
  'A free-text note about one exercise in one session, e.g. a reminder like "Back to 108" or the incline angle. At most one per session and exercise.';
comment on column public.session_exercise_notes.id is 'Client-generated UUID.';
comment on column public.session_exercise_notes.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.session_exercise_notes.session_id is 'Session the note was written in.';
comment on column public.session_exercise_notes.exercise_id is 'Exercise the note is about.';
comment on column public.session_exercise_notes.note is 'The note text (Spanish or English).';
comment on column public.session_exercise_notes.created_at is 'Row creation time (server clock).';
comment on column public.session_exercise_notes.updated_at is 'Last change (server clock, set by trigger).';
comment on column public.session_exercise_notes.deleted_at is 'Soft delete marker. Ignore rows where this is not null.';

comment on table public.planned_sessions is
  'A plan for the next session of a routine (target weights and reps). Written by the rules (generate_plan) or by Claude (submit_plan).';
comment on column public.planned_sessions.id is 'Client-generated or server-generated UUID.';
comment on column public.planned_sessions.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.planned_sessions.routine_id is 'Routine this plan is for.';
comment on column public.planned_sessions.created_by is 'rules = produced by generate_plan; claude = written by Claude. A pending claude plan wins over a pending rules plan.';
comment on column public.planned_sessions.status is 'pending = waiting to be used; used = a session was done with it; superseded = replaced by a newer plan.';
comment on column public.planned_sessions.notes is 'Free-text rationale or advice shown with the plan.';
comment on column public.planned_sessions.used_by_session_id is 'Session that consumed this plan, once status = used.';
comment on column public.planned_sessions.created_at is 'Row creation time (server clock).';
comment on column public.planned_sessions.updated_at is 'Last change (server clock, set by trigger).';

comment on table public.planned_sets is 'Target for one set of one exercise inside a planned session.';
comment on column public.planned_sets.id is 'UUID.';
comment on column public.planned_sets.user_id is 'Owner. RLS restricts every row to this user.';
comment on column public.planned_sets.planned_session_id is 'The plan this target belongs to.';
comment on column public.planned_sets.exercise_id is 'Exercise the target is for.';
comment on column public.planned_sets.set_no is 'Set number within the exercise, starting at 1. For unilateral exercises the same target applies to both L and R.';
comment on column public.planned_sets.target_weight_kg is 'Target load in kg, same conventions as sets.weight_kg (pair total for dumbbell pairs, assistance for assisted). Null = no weight target.';
comment on column public.planned_sets.target_reps_min is 'Lower end of the rep target.';
comment on column public.planned_sets.target_reps_max is 'Upper end of the rep target.';
comment on column public.planned_sets.note is 'Short advice for this set, e.g. "establish load, stop 3 reps short of failure".';
comment on column public.planned_sets.created_at is 'Row creation time (server clock).';
comment on column public.planned_sets.updated_at is 'Last change (server clock, set by trigger).';
